/**
 * React hook for fetching valid NFT listings from Bazaar
 *
 * Returns listings that are:
 * - OPEN status (not filled, cancelled, or expired)
 * - Not expired
 * - Seller still owns the NFT
 *
 * Results are deduplicated (one per token) and sorted by price (lowest first).
 * If `nftAddress` is omitted, fetches recent listings across all collections on the chain.
 *
 * @example
 * ```tsx
 * const { listings, isLoading, error } = useBazaarListings({
 *   chainId: 8453,
 *   nftAddress: "0x...",
 *   maxMessages: 100,
 * });
 *
 * if (isLoading) return <div>Loading...</div>;
 * if (error) return <div>Error: {error.message}</div>;
 *
 * return (
 *   <ul>
 *     {listings.map((listing) => (
 *       <li key={listing.orderHash}>
 *         Token #{listing.tokenId} - {listing.price} {listing.currency}
 *       </li>
 *     ))}
 *   </ul>
 * );
 * ```
 */
declare function useBazaarListings({ chainId, nftAddress, excludeMaker, maker, maxMessages, startIndex: startIndexOverride, endIndex: endIndexOverride, includeExpired, enabled, publicClient, }: UseBazaarListingsOptions): UseBazaarListingsResult;

